{
  "task": "Improve setup WNS of the native RTL without changing cycle-level behavior.",
  "constraints": [
    "Preserve top name, native ports and widths, signedness, reset polarity, enables and exact output latency.",
    "Keep a single direct positive-edge clock; do not introduce async reset, latches, memories or generated clocks.",
    "Do not add assume/assert, initial assignments or unknown/high-impedance values to evade verification.",
    "The original frozen RTL is the functional reference for every candidate, not the last candidate.",
    "Startup assumptions are fixed and identical for the original and all candidates; never extend them.",
    "Top parameter overrides and shared dependency modules are frozen. Do not redefine those helper modules in candidate_rtl.",
    "WNS is measured at fixed clock/IO/library settings. Do not claim measured improvements before EDA."
  ],
  "startup_and_timing_contract": {
    "top": "ticket_machine",
    "clock": "clk",
    "reset": "clear",
    "reset_active": 1,
    "reset_cycles": 1,
    "warmup_samples": 1,
    "reset_after_startup": "unconstrained",
    "period_ns": 10,
    "parameter_overrides": {},
    "parameter_defaults": {
      "ON": 1,
      "OFF": 0
    },
    "input_delay_ns": 0,
    "output_delay_ns": 0,
    "input_transition_ns": 0.1,
    "output_load_pf": 0.01,
    "preserve_output_latency": true,
    "library": "SKY130HD TT 025C 1v80",
    "library_sha256": "92eb4e93a3d4c2563018ac81cdec2f02fdeaced9b39337ed5c141fa63e0ad8f8"
  },
  "fixed_mapped_area_cap_um2": 278.01664000000005,
  "current_rtl": "
module ticket_machine #(
    parameter ON  = 1'b1,
    parameter OFF = 1'b0
) (
    input  clk, clear, ten, twenty,
    output reg ready, dispense, return_sig, bill
);

    // use one-hot encoding to define states
    localparam RDY    = 6'b000001,
               DISP   = 6'b000010,
               RTN    = 6'b000100,
               BILL10 = 6'b001000,
               BILL20 = 6'b010000,
               BILL30 = 6'b100000;

    reg [5:0] State, NextState;

    // update state on clock rising edge
    always @(posedge clk) begin 
        if (clear)
            State <= RDY;
        else
            State <= NextState;
    end

    // output logic based on current state (Moore state machine)
    always @(State) begin
        case (State)
            RDY:    begin
                ready     = ON;
                bill      = OFF;
                dispense  = OFF;
                return_sig = OFF;
            end

            DISP:   begin
                ready     = OFF;
                bill      = OFF;
                dispense  = ON;
                return_sig = OFF;
            end

            RTN:    begin
                ready     = OFF;
                bill      = OFF;
                dispense  = OFF;
                return_sig = ON;
            end

            BILL10: begin
                ready     = OFF;
                bill      = ON;
                dispense  = OFF;
                return_sig = OFF;
            end

            BILL20: begin
                ready     = OFF;
                bill      = ON;
                dispense  = OFF;
                return_sig = OFF;
            end

            BILL30: begin
                ready     = OFF;
                bill      = ON;
                dispense  = OFF;
                return_sig = OFF;
            end

            default: begin
                ready     = OFF;
                bill      = OFF;
                dispense  = OFF;
                return_sig = OFF;
            end
        endcase
    end

    // next state logic
    always @(State or ten or twenty) begin
        case (State)
            RDY:    begin
                if (ten)
                    NextState = BILL10;
                else if (twenty)
                    NextState = BILL20;
                else
                    NextState = RDY;
            end

            BILL10: begin
                if (ten)
                    NextState = BILL20;
                else if (twenty)
                    NextState = BILL30;
                else
                    NextState = BILL10;
            end

            BILL20: begin
                if (ten)
                    NextState = BILL30;
                else if (twenty)
                    NextState = DISP;
                else
                    NextState = BILL20;
            end

            BILL30: begin
                if (ten)
                    NextState = DISP;
                else if (twenty)
                    NextState = RTN;
                else
                    NextState = BILL30;
            end

            DISP:   begin
                    NextState = RDY;
            end

            RTN:    begin
                    NextState = RDY;
            end

            default: begin
                    NextState = RDY;
            end
        endcase
    end

endmodule",
  "fixed_dependency_sources": [],
  "response_format": {
    "candidate_rtl": "string",
    "bottleneck": "string",
    "rewrite": "string",
    "expected_timing_gain": "string",
    "area_or_other_cost": "string",
    "functional_boundaries": "string"
  },
  "functional_contract": "Preserve outputs ready, dispense, return_sig and bill for every sampled input sequence after the fixed startup reset, including ten=twenty=1 (ten has source-defined priority) and arbitrary later clear assertions. Preserve original module parameter declarations and defaults. No added init/assume, unreachable-state input assumptions, or latency changes. Proof applies to default ON=1 and OFF=0 only.",
  "objective": "Strictly improve worst setup slack without regressing TNS, within fixed area budget. Original baseline remains available. No measured gain claim before EDA.",
  "baseline_area_um2": 252.7424
}
